import random

from .error import MazeLoadError
from .config import Config
from .direction import Direction
from .pacgum import Pacgum, place_pacgums

from mazegenerator import MazeGenerator
import pygame


class Maze():
    """A maze with walls and corridors, generated by the assigned A-Maze-ing package."""
    grid: list[list[int]] = []
    pellets: Pacgum = Pacgum(set(), set())
    cell_size: int = 48
    wall_thickness = 8
    wall_color = (64, 96, 255)
    ft_color = (0, 0, 127)
    sprites: dict[str, pygame.Surface] = {}
    nb_gum: int = 0
    nb_sgum: int = 0

    def __init__(self, excluded: set[tuple[int, int]]) -> None:
            Maze.grid = Maze.load_maze()
            rng = random.Random(Config.seed)
            Maze.pellets = place_pacgums(Maze.grid, Config.pacgum, excluded, rng)
       
    @classmethod
    def load_maze(cls) -> list[list[int]]:
        """Load a maze with the given seed."""
        try:
            gen = MazeGenerator(size=(Config.width, Config.height), perfect=False, seed=Config.seed)
            return gen.maze
        except Exception as e:
            raise MazeLoadError(f"Failed to load maze: {e}") from e

    @classmethod
    def limit(cls, pos: tuple[int, int]) -> tuple[int, int]:
        x: int = 0
        y: int = 0
        x, y = pos
        if x < 0:
            x = 0
        elif x >= Config.width:
            x = Config.width - 1
        if y < 0:
            y = 0
        elif y >= Config.width:
            y = Config.width - 1
        return ((x, y))

    @classmethod
    def cell_exit(cls, pos: tuple[int, int]) -> int:
        x: int = 0
        y: int = 0
        cell: int = 0
        x, y = pos
        cell = cls.grid[y][x]
        if cell & 32:
            cell -= 32
        if cell & 16:
            cell -= 16
        return (15 - cell)

    @classmethod
    def convert_pos(cls, grid_pos: tuple[int, int]) -> tuple[int, int]:
        """Return the pixel position of the center of the cell at grid_pos."""
        grid_x: int = 0
        grid_y: int = 0
        grid_x, grid_y = grid_pos
        return ((grid_x * cls.cell_size + 8, grid_y * cls.cell_size + 8))

