    @classmethod
    def load_sprites(cls) -> None:
        if not cls.sprites:
            cls.sprites["pacgum"] = pygame.image.load(
                f"lib_pacman/{Config.sprite_pacgum}"
            ).convert_alpha()

    @classmethod
    def add_pacgum(cls) -> None:
        x:int = 0
        y:int = 0
        # Add super-pacgums in the 4 corners
        cls.grid[0][0] += 32
        cls.grid[0][Config.width - 1] += 32
        cls.grid[Config.height - 1][Config.width - 1] += 32
        cls.grid[Config.height - 1][0] += 32
        cls.nb_sgum = 4
        cls.nb_gum = 0

        # Add pacgums in few cells of the maze
        # for _ in range(Config.pacgum):
        #     x = 4
        #     y = 5
        #     while Maze.grid[y][x] >= 15:
        #         x = randint(0, 15)
        #         y = randint(0, 15)
        #     Maze.grid[y][x] += 16
        #     cls.nb_gum += 1

        # Add pacgums in all the cells of the maze
        for y, row in enumerate(cls.grid):
            for x, cell in enumerate(row):
                if cell != 15:
                    cls.grid[y][x] += 16
                    cls.nb_gum += 1

            cls.sprites["super_pacgum"] = pygame.image.load(
                f"lib_pacman/{Config.sprite_super}"
            ).convert_alpha()

            cls.sprites["42"] = pygame.image.load(
                f"lib_pacman/{Config.sprite_42}"
            ).convert_alpha()

    @classmethod
    def draw_wall(cls, area: pygame.Surface, start: tuple[int, int], end: tuple[int, int]) -> None:
        """Draw a wall between start and end on the given area."""
        pygame.draw.line(area, cls.wall_color, start, end, cls.wall_thickness)

    @classmethod
    def draw_42(cls, area: pygame.Surface, pos: tuple[int, int]) -> None:
        """Draw a 42 cell on the given area."""
        x, y = pos
        cell_42 = pygame.Rect(x, y, cls.cell_size, cls.cell_size)
        pygame.draw.rect(area, cls.ft_color, cell_42)
        sprite = pygame.image.load(f"{Config.sprite_42}").convert_alpha()
        area.blit(sprite, (x + 8, y + 8))

    @classmethod
    def draw_pacgum(cls, area: pygame.Surface, pos: tuple[int, int]) -> None:
        """Draw a pacgum on the given area."""
        x, y = pos
        sprite = cls.sprites["pacgum"]
        # sprite = pygame.image.load(f"{Config.sprite_pacgum}").convert_alpha()
        area.blit(sprite, (x + 8, y + 8))

    @classmethod
    def draw_super_pacgum(cls, area: pygame.Surface, pos: tuple[int, int]) -> None:
        """Draw a super-pacgum on the given area."""
        x, y = pos
        sprite = cls.sprites["super_pacgum"]
        # sprite = pygame.image.load(f"{Config.sprite_super}").convert_alpha()
        area.blit(sprite, (x + 8, y + 8))

    @classmethod
    def draw_maze(cls, area: pygame.Surface) -> None:
        """Draw the maze on the given area."""
        for y, row in enumerate(cls.grid):
            for x, cell in enumerate(row):
                px = x * cls.cell_size
                py = y * cls.cell_size
                #draw 42 cell
                if cell == 15:
                    cls.draw_42(area, (px, py))     
                # Draw walls           
                if cell & Direction.NORTH.value:
                    cls.draw_wall(area, (px, py), (px + cls.cell_size, py))
                if cell & Direction.EST.value:
                    cls.draw_wall(area, (px + cls.cell_size, py), (px + cls.cell_size, py + cls.cell_size))
                if cell & Direction.SOUTH.value:
                    cls.draw_wall(area, (px, py + cls.cell_size), (px + cls.cell_size, py + cls.cell_size))
                if cell & Direction.WEST.value:
                    cls.draw_wall(area, (px, py), (px, py + cls.cell_size))

                # Draw regular pacgum
                if (x, y) in cls.pellets.pacgums:
                    cls.draw_pacgum(area, (px, py))

                # Draw super-pacgum
                if (x, y) in cls.pellets.super_pacgums:
                    cls.draw_super_pacgum(area, (px, py))